/**
 * Desafio+ — services/api.js
 * Cliente axios pré-configurado para o backend.
 *
 * A URL base é lida de REACT_APP_API_URL (arquivo .env do frontend).
 * Se não estiver definida, usa http://localhost:8787/api como padrão.
 *
 * CORREÇÃO: Adicionados todos os named exports que os componentes usam.
 */

import axios from 'axios';

// ── Instância axios base ──────────────────────────────────────────────────────
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8787/api',
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json'
  }
});

// ── Interceptor: injeta token JWT em todas as requisições ─────────────────────
api.interceptors.request.use(config => {
  const token = localStorage.getItem('access_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// ── postsAPI — usado em: PostCard.js, Feed.js ─────────────────────────────────
export const postsAPI = {
  // Feed.js: postsAPI.create({ content, category, media_urls, media_type })
  create: data => api.post('/posts', data),
  // PostCard.js: postsAPI.like(post.id)
  like: postId => api.post(`/posts/${postId}/like`),
  // PostCard.js: postsAPI.getComments(post.id)
  getComments: postId => api.get(`/posts/${postId}/comments`),
  // PostCard.js: postsAPI.addComment(post.id, { content })
  addComment: (postId, data) => api.post(`/posts/${postId}/comments`, data),
  // PostCard.js: postsAPI.delete(post.id)
  delete: postId => api.delete(`/posts/${postId}`)
};

// ── feedAPI — usado em: useFeed.js ────────────────────────────────────────────
export const feedAPI = {
  // useFeed.js: feedAPI.getFeed({ limit, offset })
  getFeed: params => api.get('/feed', {
    params
  }),
  // useFeed.js: feedAPI.getExplore({ limit, offset })
  getExplore: params => api.get('/feed/explore', {
    params
  })
};

// ── notificationsAPI — usado em: useNotifications.js ─────────────────────────
export const notificationsAPI = {
  // useNotifications.js: notificationsAPI.getUnreadCount()
  getUnreadCount: () => api.get('/notifications/unread-count'),
  // useNotifications.js: notificationsAPI.getAll()
  getAll: () => api.get('/notifications'),
  // useNotifications.js: notificationsAPI.markAllRead()
  markAllRead: () => api.post('/notifications/mark-all-read')
};

// ── challengesAPI — usado em: Challenges.js ───────────────────────────────────
export const challengesAPI = {
  // Challenges.js: challengesAPI.getDaily({ mode })
  getDaily: params => api.get('/challenges/daily', {
    params
  }),
  // Challenges.js: challengesAPI.getAll({ mode, limit })
  getAll: params => api.get('/challenges', {
    params
  }),
  // Challenges.js: challengesAPI.complete({ challenge_id })
  complete: data => api.post('/challenges/complete', data),
  // Challenges.js: challengesAPI.generateAI({ mode, category })
  generateAI: data => api.post('/challenges/generate-ai', data)
};

// ── chatAPI — usado em: Chat.js ───────────────────────────────────────────────
export const chatAPI = {
  // Chat.js: chatAPI.getConversations()
  getConversations: () => api.get('/chat/conversations'),
  // Chat.js: chatAPI.getMessages(conv.id)
  getMessages: convId => api.get(`/chat/conversations/${convId}/messages`),
  // Chat.js: chatAPI.sendMessage(activeConv.id, { content })
  sendMessage: (convId, data) => api.post(`/chat/conversations/${convId}/messages`, data)
};

// ── uploadAPI — usado em: Feed.js ─────────────────────────────────────────────
export const uploadAPI = {
  // Feed.js: uploadAPI.uploadToR2(mediaFile, 'posts')
  uploadToR2: async (file, folder = 'uploads') => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('folder', folder);
    const {
      data
    } = await api.post('/upload', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    return data.url;
  }
};

// ── gamesAPI — usado em: Games.js ────────────────────────────────────────────
export const gamesAPI = {
  // Games.js: gamesAPI.recordSession({ game_slug, score, result })
  recordSession: data => api.post('/games/session', data)
};

// ── usersAPI — usado em: Profile.js, Settings.js ─────────────────────────────
export const usersAPI = {
  // Profile.js: usersAPI.getProfile(username)
  getProfile: username => api.get(`/users/${username}`),
  // Profile.js: usersAPI.getPosts(username)
  getPosts: username => api.get(`/users/${username}/posts`),
  // Profile.js: usersAPI.follow(username)
  follow: username => api.post(`/users/${username}/follow`),
  // Settings.js: usersAPI.updateProfile(form)
  updateProfile: data => api.put('/users/me', data)
};

// ── searchAPI — usado em: Search.js ──────────────────────────────────────────
export const searchAPI = {
  // Search.js: searchAPI.search(q)
  search: q => api.get('/search', {
    params: {
      q
    }
  })
};

// ── Export default (usado em AuthContext.js e outros) ─────────────────────────
export default api;

